-- migrate:up

-- Ids are UUIDv7, generated by PostgreSQL 18: unique across tables and ordered
-- by creation time, which keeps inserts friendly to B-tree indexes.

CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  -- Stored trimmed and lowercased, so the unique constraint is case-insensitive.
  email text NOT NULL,
  -- Argon2id in PHC string format. Never the password itself.
  password_hash text NOT NULL,
  display_name text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_email_normalized CHECK (
    email = lower(btrim(email)) AND char_length(email) BETWEEN 3 AND 254 AND position('@' IN email) > 1
  ),
  CONSTRAINT users_password_hash_format CHECK (password_hash LIKE '$argon2id$%'),
  CONSTRAINT users_display_name_length CHECK (char_length(btrim(display_name)) BETWEEN 1 AND 100),
  CONSTRAINT users_status_check CHECK (status IN ('active', 'disabled'))
);

CREATE TRIGGER users_set_updated_at BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE organizations (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  name text NOT NULL,
  -- Readable and stable identifier for URLs. Never the primary key.
  slug text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT organizations_slug_key UNIQUE (slug),
  CONSTRAINT organizations_slug_format CHECK (
    slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) BETWEEN 2 AND 63
  ),
  CONSTRAINT organizations_name_length CHECK (char_length(btrim(name)) BETWEEN 1 AND 100)
);

CREATE TRIGGER organizations_set_updated_at BEFORE UPDATE ON organizations
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Organizations and users are never deleted physically in this phase. Every
-- reference uses ON DELETE RESTRICT, so an accidental delete fails loudly
-- instead of silently taking memberships, keys or audit history with it.
CREATE TABLE memberships (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  organization_id uuid NOT NULL REFERENCES organizations (id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES users (id) ON DELETE RESTRICT,
  role text NOT NULL,
  status text NOT NULL DEFAULT 'active',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT memberships_role_check CHECK (role IN ('OWNER', 'ADMIN', 'MEMBER', 'VIEWER')),
  CONSTRAINT memberships_status_check CHECK (status IN ('active', 'removed'))
);

-- At most one active membership per user and organization. Removed
-- memberships stay as history, so the constraint only covers active ones.
CREATE UNIQUE INDEX memberships_active_key ON memberships (organization_id, user_id)
  WHERE status = 'active';
CREATE INDEX memberships_user_idx ON memberships (user_id) WHERE status = 'active';

CREATE TRIGGER memberships_set_updated_at BEFORE UPDATE ON memberships
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Minimal audit trail for sensitive actions. Rows are only ever inserted.
CREATE TABLE audit_events (
  id uuid PRIMARY KEY DEFAULT uuidv7(),
  organization_id uuid REFERENCES organizations (id) ON DELETE RESTRICT,
  actor_user_id uuid REFERENCES users (id) ON DELETE RESTRICT,
  action text NOT NULL,
  resource_type text NOT NULL,
  resource_id uuid,
  -- Small, non-secret context. Size is capped so it cannot become a data dump.
  metadata jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT audit_events_action_format CHECK (action ~ '^[A-Z][A-Z_]*$'),
  CONSTRAINT audit_events_metadata_object CHECK (
    jsonb_typeof(metadata) = 'object' AND pg_column_size(metadata) <= 2048
  )
);

CREATE INDEX audit_events_organization_idx ON audit_events (organization_id, created_at DESC)
  WHERE organization_id IS NOT NULL;
CREATE INDEX audit_events_actor_idx ON audit_events (actor_user_id, created_at DESC);

-- migrate:down

DROP TABLE audit_events;
DROP TABLE memberships;
DROP TABLE organizations;
DROP TABLE users;
DROP FUNCTION set_updated_at();
